import itertools

# Read input
elements = list(map(int, input().split()))
k = int(input())
try:
    top_n_line = input()
except EOFError:
    top_n = 2
else:
    if not top_n_line.strip():
        top_n = 2
    else:
        top_n = int(top_n_line.strip())

n = len(elements)

# Determine product and sums
if k <= 0 or k > n:
    product = 1
    sums = []
else:
    positions = list(range(n))
    combinations = itertools.combinations(positions, k)
    sums = [sum(elements[i] for i in comb) for comb in combinations]
    product = 1
    for s in sums:
        product *= s

# Output the results
if len(sums) == 0:
    print(product)
else:
    print(product)
    sorted_sums = sorted(sums, reverse=True)
    top_sums = sorted_sums[:top_n]
    for s in top_sums:
        print(s)
```

