import sys
import string

def is_all_punctuation(s):
    return all(c in string.punctuation for c in s)

def main():
    text = sys.stdin.read()
    tokens = text.split()

    counts = {}
    order = []

    for token in tokens:
        if token.startswith('$'):
            rest = token[1:]
            if not is_all_punctuation(rest):
                if token not in counts:
                    counts[token] = 1
                    order.append(token)
                else:
                    counts[token] += 1

    for word in order:
        print(f"{word} {counts[word]}")

if __name__ == "__main__":
    main()
```

